  try {
    const compiled = ajv.compile(schema);
    validatorsBySchema.set(schema, compiled);
    return compiled;
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

