import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('rejects input missing the required location property with a ToolResponse and never invokes the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      namesLocationAsRequired: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      namesLocationAsRequired: true,
    });
  });

  it('passes undeclared extra properties through to the executor unchanged and exactly once', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        executorInputs.push(input);
        return 'ok';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Paris', unit: 'metric'});

    expect({result: response.result, executorInputs}).toEqual({
      result: 'ok',
      executorInputs: [{location: 'Paris', unit: 'metric'}],
    });
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('no_such_tool', {})).rejects.toThrow('Unknown tool: no_such_tool');
  });

  it('validates a function-valued definition against the inputSchema returned for the current call', async () => {
    const registry = new ToolRegistry();
    const permissiveSchema: Record<string, unknown> = {type: 'object', properties: {}, required: []};
    const requiringSchema: Record<string, unknown> = {
      type: 'object',
      properties: {id: {type: 'string'}},
      required: ['id'],
    };
    let currentSchema: Record<string, unknown> = permissiveSchema;
    registry.register(
      () => ({
        name: 'shifting_tool',
        description: 'Returns a different schema per call',
        inputSchema: currentSchema,
      }),
      async () => 'ok'
    );

    const permissive = await registry.execute('shifting_tool', {});
    currentSchema = requiringSchema;
    const rejecting = await registry.execute('shifting_tool', {});
    const accepting = await registry.execute('shifting_tool', {id: 'a-1'});

    expect({
      permissive: permissive.result,
      rejectsMissingId: rejecting.result.includes('id') && /required/i.test(rejecting.result),
      accepts: accepting.result,
    }).toEqual({
      permissive: 'ok',
      rejectsMissingId: true,
      accepts: 'ok',
    });
  });

  it('compiles a static tool inputSchema once and reuses it across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let propertiesReads = 0;
    registry.register(
      {
        name: 'compiled_once',
        description: 'Counts reads of the properties keyword',
        inputSchema: {
          type: 'object',
          get properties() {
            propertiesReads += 1;
            return {location: {type: 'string'}};
          },
          required: ['location'],
        },
      },
      async () => 'ok'
    );
    const readsAfterRegister = propertiesReads;
    let lastResult = '';
    for (let call = 0; call < 10; call++) {
      const response = await registry.execute('compiled_once', {location: `place-${call}`});
      lastResult = response.result;
    }

    expect({lastResult, readsDuringExecutes: propertiesReads - readsAfterRegister}).toEqual({
      lastResult: 'ok',
      readsDuringExecutes: 0,
    });
  });
});

